import{_t as e,it as t,n,rt as r}from"./chunks/framework.BmT8T0yb.js";import{$ as i}from"./chunks/assets.DX-01Jo8.js";var a=JSON.parse(`{"title":"Console Logging","description":"","frontmatter":{"qt_version":"6.12.0"},"headers":[],"relativePath":"en/qgc-user-guide/troubleshooting/console_logging.md","filePath":"en/qgc-user-guide/troubleshooting/console_logging.md"}`),o={name:`en/qgc-user-guide/troubleshooting/console_logging.md`};function s(n,a,o,s,c,l){return e(),r(`div`,null,[...a[0]||=[t(`<h1 id="console-logging" tabindex="-1">Console Logging <a class="header-anchor" href="#console-logging" aria-label="Permalink to “Console Logging”">​</a></h1><p>The <em>App Log Viewer</em> can be a helpful tool for diagnosing <em>QGroundControl</em> problems. It can be found in <strong>Application Settings &gt; App Log Viewer</strong>.</p><p><img src="`+i+`" alt="App Log Viewer" width="1137" height="752"></p><p>Click the <strong>Categories</strong> button to enable/disable the logging categories displayed by <em>QGroundControl</em>.</p><h2 id="common-logging-categories" tabindex="-1">Common Logging Categories <a class="header-anchor" href="#common-logging-categories" aria-label="Permalink to “Common Logging Categories”">​</a></h2><p>The most commonly used logging categories are listed below.</p><table tabindex="0"><thead><tr><th>Category(s)</th><th>Description</th></tr></thead><tbody><tr><td><code>Comms.LinkManager</code>, <code>Vehicle.MultiVehicleManager</code></td><td>Debug connection problems.</td></tr><tr><td><code>Comms.LinkManager:verbose</code></td><td>Debug serial ports not being detected. Very noisy continuous output of available serial ports.</td></tr><tr><td><code>VehicleSetup.FirmwareUpgrade</code></td><td>Debug firmware flash issues.</td></tr><tr><td><code>FactSystem.ParameterManager</code></td><td>Debug parameter load problems.</td></tr><tr><td><code>FactSystem.ParameterManager:debugCacheFailure</code></td><td>Debug parameter cache crc misses.</td></tr><tr><td><code>PlanManager.PlanManager</code>, <code>PlanManager.MissionManager</code>, <code>PlanManager.GeoFenceManager</code>, <code>PlanManager.RallyPointManager</code></td><td>Debug Plan upload/download issues.</td></tr><tr><td><code>AutoPilotPlugins.RadioComponentController</code></td><td>Debug Radio calibration issues.</td></tr></tbody></table><h2 id="logging-from-the-command-line" tabindex="-1">Logging from the Command Line <a class="header-anchor" href="#logging-from-the-command-line" aria-label="Permalink to “Logging from the Command Line”">​</a></h2><p>An alternate mechanism for logging is using the <code>--logging</code> command line option. This is handy if you are trying to get logs from a situation where <em>QGroundControl</em> crashes.</p><p>Two options work together:</p><ul><li><code>--logging:full</code> (or <code>--logging:&lt;comma-separated categories&gt;</code>) enables the logging categories.</li><li><code>--log-output</code> writes the log messages to stderr (the terminal on macOS/Linux). Without it, messages are only visible in the <em>App Log Viewer</em> and the <strong>AppLog.log</strong> file in the application log directory.</li></ul><p>How you do this and where the traces are output vary by OS:</p><ul><li><p>Windows</p><ul><li><p>Open a command prompt and run <em>QGroundControl</em> from its install location (the installer default is shown below). Because <em>QGroundControl</em> is a GUI application it has no console window, so stderr isn&#39;t displayed — redirect it to a file to capture it:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;%ProgramFiles%\\QGroundControl\\bin&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">QGroundControl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --logging:full</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --log-output</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;%USERPROFILE%\\qgc_log.txt&quot;</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> 2&gt;&amp;1</span></span></code></pre></div></li></ul></li><li><p>macOS</p><ul><li><p>You must run <em>QGroundControl</em> from Terminal. The Terminal app is located in <strong>Applications/Utilities</strong>. Once Terminal is open paste the following into it:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /Applications/QGroundControl.app/Contents/MacOS</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./QGroundControl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --logging:full</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --log-output</span></span></code></pre></div></li><li><p>Log traces will output to the Terminal window.</p></li></ul></li><li><p>Linux</p><ul><li><p>Run the AppImage from a terminal:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./QGroundControl-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;arch&gt;.AppImage </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">--logging:full</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --log-output</span></span></code></pre></div></li><li><p>Log traces will output to the shell you are running from.</p></li></ul></li></ul><h2 id="android-usb-serial-logging" tabindex="-1">Android USB Serial Logging <a class="header-anchor" href="#android-usb-serial-logging" aria-label="Permalink to “Android USB Serial Logging”">​</a></h2><p>On Android, <em>QGroundControl</em> talks to USB serial devices (flight controllers, telemetry radios, GPS) through a Java layer and a C++ layer. Three logs show what this code is doing on a device, whether you are developing it or debugging a link in the field. All three go to the Android system log, which you read from a computer with <a href="https://developer.android.com/tools/adb" target="_blank" rel="noreferrer"><code>adb</code></a>. Most of it also reaches <em>QGroundControl</em>&#39;s own console log, which needs no computer.</p><h3 id="device-and-port-events" tabindex="-1">Device and Port Events <a class="header-anchor" href="#device-and-port-events" aria-label="Permalink to “Device and Port Events”">​</a></h3><p>The Java layer reports USB attach and detach events, USB permission, and ports being opened under log tags that start with <code>QGCUsbSerial</code>, most of it under <code>QGCUsbSerialDevices</code> and <code>QGCUsbSerialPort</code>. This log is always on. To view it:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">adb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logcat</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> QGCUsbSerialDevices</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> QGCUsbSerialPort</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> QGCUsbSerialReader</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> QGCUsbSerialWriter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> QGCUsbSerialManager</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> QGCUsbSerialAndroidHost</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> QGCUsbSerialPortName</span></span></code></pre></div><p>Example messages (the <code>I/O stopped</code> line is what an unplug looks like; one that interrupts a write also logs <code>Write failed on port 1</code>):</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>QGCUsbSerialDevices: Added driver for /dev/bus/usb/001/014</span></span>
<span class="line"><span>QGCUsbSerialDevices: Opened /dev/bus/usb/001/014 as port 1</span></span>
<span class="line"><span>QGCUsbSerialAndroidHost: android.hardware.usb.action.USB_DEVICE_DETACHED: /dev/bus/usb/001/014</span></span>
<span class="line"><span>QGCUsbSerialPort: I/O stopped for port 1: java.io.IOException: Queueing USB request failed</span></span></code></pre></div><p>When a port closes, one line sums up what crossed it:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>QGCUsbSerialPort: Closing port 1: RX 52311 bytes, transfers 912, pauses 0, status check retries 0; TX 2104 bytes, chunks 97, discarded bytes 0</span></span></code></pre></div><p><code>pauses</code> counts how often the port stopped reading the device because the app had no room for more input. <code>status check retries</code> counts how often a read went on after the device failed to answer a status request. <code>discarded bytes</code> is the output that the app discarded before it was sent.</p><p>These messages also reach <em>QGroundControl</em>&#39;s own console log (see the <a href="#console-logging">start of this page</a>), which needs no computer. Warnings and errors always appear there. The other messages appear once the logging category <code>Android.AndroidSerial.Java</code> is enabled. A message that takes this way shows up a second time in the Android system log, under the app&#39;s own tag.</p><h3 id="byte-level-trace" tabindex="-1">Byte-Level Trace <a class="header-anchor" href="#byte-level-trace" aria-label="Permalink to “Byte-Level Trace”">​</a></h3><p>The bytes of each transfer on a port can be traced. The trace is off by default, and there are two ways to turn it on: in the app, or from a computer.</p><h4 id="in-the-app" tabindex="-1">In the App <a class="header-anchor" href="#in-the-app" aria-label="Permalink to “In the App”">​</a></h4><p>Enable the logging category <code>Android.AndroidSerialPort:trace</code>, like any other logging category (see the <a href="#console-logging">start of this page</a>). The trace then appears in <em>QGroundControl</em>&#39;s console log. Each transfer is one line showing the port, direction, byte count, and up to the first 32 bytes in hex, with <code>...</code> after them when the transfer was longer:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/dev/bus/usb/001/014 TX 21: FD 09 00 00 28 FF BE 00 00 00 00 00 00 00 06 08 C0 04 03 21 68</span></span>
<span class="line"><span>/dev/bus/usb/001/014 RX 4: FB BE 00 00</span></span></code></pre></div><p>If the app cannot keep up with the input of a port whose read buffer is limited, such as a GPS, the port stops reading the device until the app has room again, and the input waits in the adapter meanwhile. The trace marks the start and the end of such a pause:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/dev/bus/usb/001/014 RX paused</span></span>
<span class="line"><span>/dev/bus/usb/001/014 RX resumed</span></span></code></pre></div><p>This trace also covers the serial ports of the device itself (<code>/dev/tty*</code>), if the app is set to use them.</p><h4 id="from-a-computer" tabindex="-1">From a Computer <a class="header-anchor" href="#from-a-computer" aria-label="Permalink to “From a Computer”">​</a></h4><p>The Java layer traces the transfers of a USB port to the Android system log. To turn that trace on, without rebuilding or restarting the app, and watch it:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">adb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> shell</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> setprop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> log.tag.QGCSerial</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> VERBOSE</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">adb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logcat</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> QGCSerial</span></span></code></pre></div><p>Each transfer is one line, as in the app, with the port ID in place of the port&#39;s name:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>port 1 TX 21: FD 09 00 00 28 FF BE 00 00 00 00 00 00 00 06 08 C0 04 03 21 68</span></span>
<span class="line"><span>port 1 RX 4: FB BE 00 00</span></span></code></pre></div><p>The port ID is the number in the <code>Opened ... as port N</code> message of the <a href="#device-and-port-events">device and port events</a>. Port setting changes are traced too:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>port 1 parameters: 57600 baud, 8 data bits, stop bits 1, parity 0</span></span></code></pre></div><p>A <code>TX</code> line shows a whole write. If the app discards its output before all of it is sent, a line follows that says how much was sent:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>port 1 TX discarded after 1024 of 2500 bytes</span></span></code></pre></div><p>A pause of the input is marked as in the app:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>port 1 RX paused</span></span>
<span class="line"><span>port 1 RX resumed</span></span></code></pre></div><p>To turn the trace off again, set the property to an empty value (a reboot also clears it):</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">adb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> shell</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> setprop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> log.tag.QGCSerial</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;&quot;&quot;&#39;</span></span></code></pre></div><h3 id="c-logging-categories" tabindex="-1">C++ Logging Categories <a class="header-anchor" href="#c-logging-categories" aria-label="Permalink to “C++ Logging Categories”">​</a></h3><p>The C++ layer logs to the categories <code>Android.AndroidSerial</code>, <code>Android.AndroidSerialPort</code>, and <code>Android.AndroidSerialPortInfo</code>. Warnings always appear; debug output must be enabled, like any other logging category (see the <a href="#console-logging">start of this page</a>). A debug build can also enable it for one run: launch the app with the <a href="#logging-from-the-command-line"><code>--logging</code> option</a>, which on Android is passed as an intent extra. A release build, which the published daily and stable builds are, ignores that extra:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">adb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> shell</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> am</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> org.mavlink.qgroundcontrol/.QGCActivity</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> applicationArguments</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;&quot;--logging:Android.AndroidSerial,Android.AndroidSerialPort&quot;&#39;</span></span></code></pre></div><p>The lines appear in the Android system log under the app&#39;s own tag, which is <code>QGroundControl_Daily</code> for a daily build (<code>adb logcat -s QGroundControl_Daily</code>). They end with the category and function:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Opening &quot;/dev/bus/usb/001/014&quot; - Android.AndroidSerialPort - (QSerialPort::_openDevice:125)</span></span>
<span class="line"><span>USB serial devices changed - Android.AndroidSerial - (AndroidSerial::jniDevicesChanged:282)</span></span></code></pre></div>`,50)]])}var c=n(o,[[`render`,s]]);export{a as __pageData,c as default};